"""User-supplied cafeteria sample photographs, reduced for offline thumbnails."""
import base64
from pathlib import Path

SAMPLE_IMAGES = {
    'adobo.png': '',
    'burger.png': '',
    'water.png': '',
    'fries.png': '',
    'turon.png': '',
    'iced_tea.png': '',
    'siomai.png': '',
    'pancit.png': '',
    'sandwich.png': '',
}

def ensure_sample_images(base: Path) -> None:
    target = base / "images"
    target.mkdir(parents=True, exist_ok=True)
    for filename, encoded in SAMPLE_IMAGES.items():
        payload = base64.b64decode(encoded)
        file = target / filename
        if not file.exists() or file.read_bytes() != payload:
            file.write_bytes(payload)